-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/silver/silver_patient.sql. Do not edit.
-- Silver patient: one row per patient, typed, deduplicated on resource id (newest load wins).
CREATE OR REPLACE TABLE silver_patient AS
WITH latest AS (
    SELECT *
    FROM bronze_resources
    WHERE resource_type = 'Patient'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
),
typed AS (
    SELECT
        resource_id                                            AS patient_id,
        CASE
            WHEN 'hl7v2' IN (raw:meta.tag[0].code::string, raw:meta.tag[1].code::string, raw:meta.tag[2].code::string) THEN 'hl7v2'
            WHEN LOWER(COALESCE(raw:meta.profile[0]::string, '')) LIKE '%mimic%'     THEN 'mimic'
            WHEN LOWER(COALESCE(raw:identifier[0].system::string, '')) LIKE '%synthea%'
              OR LOWER(COALESCE(raw:identifier[0].system::string, '')) LIKE '%synthetichealth%' THEN 'synthea'
            ELSE 'unknown'
        END                                                    AS source,
        raw:identifier[0].value::string                          AS identifier_0,
        raw:identifier[1].value::string                          AS identifier_1,
        raw:name[0].family::string                               AS family_raw,
        raw:name[0].given[0]::string                             AS given_raw,
        raw:gender::string                                       AS gender,
        TRY_CAST(raw:birthDate::string AS DATE)                  AS birth_date,
        TRY_CAST(SUBSTR(raw:deceasedDateTime::string, 1, 19) AS TIMESTAMP_NTZ)                           AS deceased_at,
        raw:deceasedBoolean::string                              AS deceased_flag,
        raw:address[0].city::string                              AS city,
        raw:address[0].state::string                             AS state,
        raw:address[0].postalCode::string                        AS postal_code,
        source_file,
        loaded_at
    FROM latest
)
SELECT
    patient_id,
    source,
    -- Synthea keeps the medical record number in its second identifier
    CASE WHEN source = 'synthea' THEN identifier_1 ELSE identifier_0 END        AS mrn,
    -- Synthea appends digits to names (Hickle134), so strip them there only.
    -- MIMIC names are Patient_10014729: the digits are the MIMIC subject id and must stay.
    CASE WHEN source = 'synthea' THEN REGEXP_REPLACE(family_raw, '[0-9]+$', '') ELSE REPLACE(family_raw, '_', ' ') END AS family_name,
    CASE WHEN source = 'synthea' THEN REGEXP_REPLACE(given_raw, '[0-9]+$', '') ELSE given_raw END                     AS given_name,
    gender,
    birth_date,
    deceased_at,
    CASE WHEN deceased_at IS NOT NULL OR deceased_flag = 'true' THEN TRUE ELSE FALSE END AS is_deceased,
    city,
    state,
    postal_code,
    source_file,
    loaded_at
FROM typed;
